// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address newOwner) public {
        // newOwner can be any address, including zero. No assume restricts it.
        vm.prank(c.owner());
        try c.transferOwnership(newOwner) { } catch { }
        // The reference version ensures owner is not address(0) after any transferOwnership call;
        // the mutant allows owner to become address(0).
        assertTrue(c.owner() != address(0));
    }
}
